<?php require_once __DIR__.'/../php/includes/bootstrap.php';require_role('administrator');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['payment_id'],$_POST['decision'])){$id=(int)$_POST['payment_id'];$decision=$_POST['decision']==='paid'?'paid':'rejected';$s=$pdo->prepare("UPDATE payments SET status=?,verified_by=?,verified_at=NOW() WHERE id=? AND status='pending'");$s->execute([$decision,current_user()['id'],$id]);$q=$pdo->prepare('SELECT student_id,reference FROM payments WHERE id=?');$q->execute([$id]);if($payment=$q->fetch())notify($pdo,(int)$payment['student_id'],'Your payment '.$payment['reference'].' was '.$decision.'.');set_flash('Payment decision saved.');redirect('admin.php');}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['new_tutor_email'])){$name=trim($_POST['new_tutor_name']??'');$email=trim($_POST['new_tutor_email']??'');$password=$_POST['new_tutor_password']??'';$bio=trim($_POST['biography']??'');$expertise=$_POST['programme_ids']??[];if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||!is_array($expertise)||!$expertise){$error='Enter valid tutor details, a password of at least 8 characters, and at least one programme.';}else{$check=$pdo->prepare('SELECT id FROM users WHERE email=?');$check->execute([$email]);if($check->fetch())$error='That email address is already registered.';else{try{$pdo->beginTransaction();$s=$pdo->prepare("INSERT INTO users(full_name,email,password_hash,role) VALUES(?,?,?,'tutor')");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO tutors(user_id,biography) VALUES(?,?)')->execute([$id,$bio]);$link=$pdo->prepare('INSERT INTO tutor_programmes(tutor_id,programme_id) VALUES(?,?)');foreach($expertise as $pid)$link->execute([$id,(int)$pid]);$pdo->commit();set_flash('Tutor account created. Share the login details securely.');redirect('admin.php');}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error='Tutor account could not be created.';}}}}
$pending=$pdo->query("SELECT pay.*,u.full_name student,p.name programme FROM payments pay JOIN users u ON u.id=pay.student_id JOIN programmes p ON p.id=pay.programme_id WHERE pay.status='pending' ORDER BY pay.created_at")->fetchAll();$bookings=$pdo->query("SELECT b.*,s.full_name student,t.full_name tutor,p.name programme FROM bookings b JOIN users s ON s.id=b.student_id JOIN users t ON t.id=b.tutor_id JOIN programmes p ON p.id=b.programme_id ORDER BY b.session_date DESC,b.start_time DESC LIMIT 30")->fetchAll();$programmes=$pdo->query('SELECT id,name FROM programmes WHERE active=1 ORDER BY name')->fetchAll();$users=$pdo->query('SELECT id,full_name,email,role,created_at FROM users ORDER BY created_at DESC LIMIT 30')->fetchAll();page_header('Administration'); ?>
<?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><section class="panel"><h2>Pending payment requests</h2><?php if(!$pending): ?><p class="muted">No payments need review.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Student</th><th>Programme</th><th>Amount</th><th>Reference</th><th>Decision</th></tr></thead><tbody><?php foreach($pending as $pay): ?><tr><td><?=e($pay['student'])?></td><td><?=e($pay['programme'])?></td><td>R <?=number_format((float)$pay['amount'],2)?></td><td><?=e($pay['reference'])?></td><td><form class="inline-form" method="post"><input type="hidden" name="payment_id" value="<?=$pay['id']?>"><button class="button small" name="decision" value="paid">Approve</button><button class="button small secondary" name="decision" value="rejected">Reject</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="panel"><h2>Create a tutor account</h2><p class="muted">Tutor accounts are created by an administrator and assigned programme expertise.</p><form method="post" class="admin-form"><label>Full name<input name="new_tutor_name" required></label><label>Email<input type="email" name="new_tutor_email" required></label><label>Temporary password<input type="password" name="new_tutor_password" minlength="8" required></label><label>Biography<textarea name="biography" rows="3"></textarea></label><fieldset><legend>Programme expertise</legend><?php foreach($programmes as $p): ?><label class="check-label"><input type="checkbox" name="programme_ids[]" value="<?=$p['id']?>"> <?=e($p['name'])?></label><?php endforeach; ?></fieldset><button class="button" type="submit">Create tutor</button></form></section>
<section class="panel"><h2>Recent bookings</h2><?php if(!$bookings): ?><p class="muted">No bookings yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Student</th><th>Tutor</th><th>Programme</th><th>Date</th><th>Time</th><th>Status</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><?=e($b['student'])?></td><td><?=e($b['tutor'])?></td><td><?=e($b['programme'])?></td><td><?=e($b['session_date'])?></td><td><?=e(substr($b['start_time'],0,5))?>–<?=e(substr($b['end_time'],0,5))?></td><td><?=e($b['status'])?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="panel"><h2>Recent user accounts</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Created</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php page_footer(); ?>